import math

def is_good_fraction(a, b):
    m = a * b
    return m + 1 > b and b + 1 > m and (m + 1) % b == 0 and (b + 1) % m == 0

def count_good_pairs(N):
    count = 0
    for i in range(1, N+1):
        for j in range(1, N+1):
            if is_good_fraction(i, j):
                count += 1
    return count

