def is_wavey(num, n):
    # Convert number to string to facilitate comparison
    num_str = str(num)
    for i in range(1, len(num_str) - 1):
        # Check if current digit is greater than both neighbors
        if num_str[i] < num_str[i - 1] and num_str[i] < num_str[i + 1]:
            return False
        # Check if current digit is less than both neighbors
        if num_str[i] > num_str[i - 1] and num_str[i] > num_str[i + 1]:
            return False
    return True

def find_kth_wavy(n, k):
    count = 0
    i = 1
    while True:
        candidate = n * i
        if candidate > 10**14:
            return -1
        if is_wavey(candidate, n):
            count += 1
        if count == k:
