import sys
from collections import defaultdict

def read_input():
    n = int(input().strip())
    edges = [tuple(map(int, input().strip().split())) for _ in range(n)]
    return n, edges

def find_minimum_inconvenience(n, edges):
    graph = defaultdict(list)
    is_impossible = [False] * (n + 1)
    shortest_distances = [float('inf')] * (n + 1)

    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    for town in range(1, n + 1):
        is_impossible[town] = any(edge[0] == town for edge in edges) or any(edge[1] == town for edge in edges)

    for town, d in enumerate(shortest_distances):
        if is_impossible[town]:
            continue
        for neighbor, weight in graph[town]:
            if shortest_distances[neighbor] > d + weight:
                shortest_distances[neighbor] = d + weight

    return max(shortest_distances[1:])

n, edges = read_input()
