def max_sign_height(n, heights, q_queries):
    panel_highest = []
    best_height = 0

    for i in range(n):
        idx = bisect_left(panel_highest, heights[i] - q_queries[i])
        if idx == len(panel_highest):
            panel_highest.append(heights[i] - q_queries[i])
        elif panel_highest[idx] < heights[i] - q_queries[i]:
            panel_highest[idx] = heights[i] - q_queries[i]
        best_height = max(best_height, panel_highest[idx] + q_queries[i])

    panel_heights = sorted(panel_highest)
    row_highest = []

    for h in panel_heights:
        if not row_heights or row_heights[-1] != h:
            row_heights.append(h)

    for i in range(n):
        idx = bisect_left(row_highest, heights[i] - q_queries[i])
        if idx == len(row_heights):
            row_highest.append(heights[i] - q_queries[i])
        elif row_highest[idx] < heights[i] - q_queries[i]:
            row_highest[idx] = heights[i] - q_queries[i]

    max_heights = []
    for idx in range(len(panel_highest)):
        max_heights.append(sorted([panel_heights[panel_highest[idx]], q_queries[i]], reverse=True)[0] + q_queries[i])
    return max_heights

