import math

class Tree:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.leafs = {(i + 1) for i in range(n) if i not in {1}}
        self.primes = self.generate_primes(m)
        self.node = [None] * (n + 1)
        self.dep = [0] * (n + 2)

    def generate_primes(self, n):
        return [i for i in range(n) if all(i % j) for j in range(2, int(math.sqrt(i)) + 1)]

    def build_tree(self):
        self.tree = [[] for i in range(self.n + 2)]
        for i in range(self.n):
            self.dep[i + 1] = self.dep[i] + 1
            self.tree[self.dep[i] + 1].append((i + 1))
        for i in range(self.n - 1):
            u, v = list(map(int, input().split()))
            self.tree[self.dep[u]].append(u)
            self.tree[self.dep[v]].append(v)
            self.dep[u] += 1
            self.dep[v] += 1

    def update(self, node, value, low, high, qi, qj):
        if low >= qj or high <= qi:
            return
        if low >= qi and high <= qj:
            self.node[node] += value
            return
        win = min(high, qj) - max(low, qi)
        mid = (low + high) // 2
        self.update(node * 2, value, low, mid, qi, qj)
        self.update(node * 2 + 1, value, mid, high, qi, qj)
        if self.node[node * 2] > self.node[node * 2 + 1]:
            self.node[node] = self.node[node * 2]
        else:
            self.node[node] = self.node[node * 2 + 1]


    def query(self, node, low, high, i):
        if low >= i or high <= i:
            if self.node[node] != None:
                if self.node[node] in self.primes:
                    return (self.dep[i] - 1) - (self.dep[0] - self.dep[i + 1])
                else:
                    return 0
            else:
                return 0
        win = min(high, i) - max(low, i)
        mid = (low + high) // 2
        return self.query(2 * node, low, mid, i) + self.query(2 * node + 1, mid + 1, high, i)


def get_input():
    n, m = map(int, input().split())
    values = list(map(int, input().split()))
    primes = Tree(n, m).generate_primes(m)
    return n, primes, values, primes.query(1, 0, n + 1, 1) - 1

