def min_rooms_for_mood_cycle(n, m, doors):
    # Create a graph of rooms and edges
    graph = [[] for _ in range(n)]
    for i, j, c, d in doors:
        graph[i - 1].append((j - 1, c, d))
        graph[j - 1].append((i - 1, c, d))

    # BFS to find the shortest path from each room to a room we can't visit
    visited = [False] * n
    def shortest_path_to_unvisited(room):
        queue = [(room, 0)]
        visited[room] = True
        while queue:
            current, distance = queue.pop(0)
            for next_room, c, d in graph[current]:
                if not visited[next_room] and next_room == current:
                    continue
                if distance >= visited[next_room] + c:
                    visited[next_room] = distance + c
                    queue.append((next_room, distance + c))
    odd_circuits, even_circuits = set(), set()
    for i in range(n):
        shortest_path_to_unvisited(i)
        if visited.count(True) % 2:
            odd_circuits.add(visited.count(True))
        else:
            even_circuits.add(visited.count(True))

    # If there are both odd and even circuits, find the minimum size of one of them
    if odd_circuits and even_circuits:
        min_odd_circuit = min(odd_circuits)
        for even_circuit in even_circuits:
            if even_circuit + min_odd_circuit < min_odd_circuit:
                min_odd_circuit = even_circuit + min_odd_circuit
        return min_odd_circuit
    else:
        return min(odd_circuits or even_circuits)


