from collections import defaultdict

def is_bipartite(graph):
    colors = [0] * len(graph)  # 0 for not colored, 1 for red, -1 for blue
    color_test = 1  # beginning with color 1

    def bfs(start):
        queue = [start]
        while queue:
            u = queue.pop(0)
            for neighbor in graph[u]:
                if colors[u] == colors[neighbor]:
                    return False
                if not colors[neighbor]:
                    colors[neighbor] = color_test
                    queue.append(neighbor)
            color_test *= -1
        return True

    for v in range(len(graph)):
        if not colors[v]:
            if not bfs(v):
                return False
    return True

def find_bipartite_permutation(permutation):
    n = len(permutation)
    graph = defaultdict(list)
    index_map = defaultdict(list)

    for i in range(n):
        index_map[permutation[i]].append(i)

    for vertex in index_map:
        graph[vertex].extend(index_map[-vertex])

    visited = [False] * n
    found_permutation = False

    def dfs(start, parent):
        visited[start] = True
        for neighbor in graph[start]:
            if not visited[neighbor]:
                parent[neighbor] = start
                dfs(neighbor, parent)
            elif parent[neighbor] != start:
                found_permutation = True
                return
        if found_permutation:
            return
        for neighbor in graph[start]:
            dfs(neighbor, None)

    for vertex in index_map:
        if not visited[vertex] and dfs(vertex,[vertex]):
            return "YES", [-1 * a for a in permutation[index_map[vertex]]]
    return "NO"

