from collections import defaultdict

def find_parent(parent, i):
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    px = find_parent(parent, x)
    py = find_parent(parent, y)
    if px == py:
        return 
    else:
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

def dfs(parent, visited, start, global_count):
    global_count += 1
    visited.append(start)
    for child in find_parent(parent, start):
        if child not in visited:
            dfs(parent, visited, child, global_count)
    return global_count

