    rank = defaultdict(int)
    for i in range(N):
        parent[i] = i
        rank[i] = 0

    # Union by Rank
    for u, v in shuttle_flights:
        union(parent, rank, u - 1, v - 1)

    # Now send DFS exploration from each node sorted in terms of parent so count is 1
    global_count = 0
    count = defaultdict(int)
