from queue import Queue

def get_free_flight_options(n_ppl, flights, ppl_order):
    flight_options = []
    graph = fill_graph(flights, ppl_order)
    available_flights = PriorityQueue()
    cost = {}

    for i in range(n_ppl):
        if ppl_order[i] == 'X':
            available_heads = available_flights.find_flights_for_head(0, False)
        elif ppl_order[i] == 'Y':
            available_heads = available_flights.find_flights_for_head(4, True)
        elif ppl_order[i] == 'Z':
            available_heads = available_flights.find_flights_for_head(5, False)

        while available_heads:
            flight_from, flight_to, cost_of_flight = available_heads.get()
            if cost.get(flight_to, -1) == -1:
                cost[flight_to] = cost_of_flight
                flight_options.append(str(flight_to))
            elif cost_of_flight > cost[flight_to]:
                cost[flight_to] = cost_of_flight
                flight_options[flight_to] = flight_options[flight_to] + '; ' + str(flight_to)
            available_heads = available_flights.find_flights_for_head(flight_from, False)

        while cost:
            flight_to = min(cost, key=lambda i:int(i))
            availability = []
            for (flight_from, flight_to, next_cost) in available_flights.filter_for_targets(flight_to, flight_options):
                cost_of_flight = int(flight_options[flight_to])
                if cost_of_flight > next_cost:
                    availability.append((flight_from, flight_to, next_cost, cost_of_flight))
                    cost[flight_to] = cost[flight_to] + next_cost - cost_of_flight
            available_heads = Queue()
            for ffa in availability:
                available_heads.put(ffa)

    for flight_to in list(cost.keys()):
        flight_options.append(str(flight_to))

    return flight_options

def fill_graph(flights, ppl_order):
    graph = {i: [] for i in range(len(ppl_order))}
    for (initial, final), cost in flights:
        graph[initial].append((final, cost, 1))
        graph[final].append((initial, cost, 0))

    for i in range(len(ppl_order)):
        if ppl_order[i] == 'X':
            graph[0].append((i, '', 2))
            for j in range(1, len(ppl_order)):
                if ppl_order[j] != 'X' and ppl_order[j] == 'Y' or ppl_order[j] == 'Z':
                    if ppl_order[i] < ppl_order[j]:
                        graph[i].append((j, '', 3))
    return graph

def filter_for_targets(target, flight_options):
    return ((f[0], f[1], f[2]) for f in flight_options if f[0] == target or f[1] == target)

if __name__ == "__main__":
    n, m = tuple(map(int, input().strip().split()))
    flights = [tuple(map(int, i.split())) for i in input().split("XXXXYYYYZZZ")[1:]]
    ppl_order = ''.join(input().strip()[:n])

    print(get_free_flight_options(n, flights, ppl_order))
