from collections import defaultdict

def merge_sequences(x, y, l1, r1, l2, r2):
    count = defaultdict(int)

    def helper(i, j):
        if i < l1 or j < l2:
            return 0
        count[0] += l1-j+1
        count[1] += r1-i+1
        if i == l1 and j == l2:
            return 1
        if r1 >= r2:
            if j == l2:
                return 1
            return helper(i+1, j+1) + count[1] - count[0]
        else:
            if i == l1:
                return helper(i+1, j) + count[0] - count[1]
            return count[0] - count[1]

    return sum(helper(i, j) for i in range(l1, l1-r1+1) for j in range(l2, l2-r2+1))

