from heapq import heappop, heappush

def dijkstra(graph, start, end, distance, visited):
    queue = []
    distance[start] = 0
    heappush(queue, (0, start))
    while queue:
        current_distance, current_vertex = heappop(queue)
        if visited[current_vertex]:
            continue
        visited[current_vertex] = True
        for neighbor, weight in graph[current_vertex].items():
            new_distance = current_distance + weight
            if new_distance < distance.get(neighbor, float('inf')):
                distance[neighbor] = new_distance
                heappush(queue, (new_distance, neighbor))
    if distance.get(end, float('inf')) != float('inf'):
        return distance[end]
    return float('inf')

def find_min_rooms_to_cycle(m):
