import sys

def find_bipartite_permutation(n, permutation):
    """Find a bipartite permutation using Goldblatt's theorem."""
    odd_points = []
    for i in range(n):
        if permutation[i] * sign(i) < 0:
            odd_points.append(i)
        else:
            odd_points = []
        if not odd_points:
            return "NO"
        for j in odd_points:
            if permutation[j] * sign(i) < 0:
                return "NO"
        for j in range(n - 2, j + 1, -1):
            if sign(i) * permutation[j] > sign(j + 1):
                return "NO"
    return "YES" + " ".join(map(str, permutation))

def sign(i):
    return 1 if i >= 0 else -1

